INSERT IGNORE INTO books (slug, title, author, publisher, category_id, price, off, pages, pub_year, isbn, stock, published_on, book_rank, pal, orn, description, active) VALUES
('bof-kur', 'بوف کور', 'صادق هدایت', 'نشر امیرکبیر', 1, 185000, 10, 148, 1402, '978-964-00-0001-1', 12, '2026-09-14', 3, 4, 0, 'بوف کور، مشهورترین رمان صادق هدایت، روایتی سوررئال از تنهایی، اضطراب و جست‌وجوی معناست. این رمان کوتاه از تأثیرگذارترین آثار ادبیات مدرن فارسی به شمار می‌رود و همچنان خوانندگان تازه‌ای پیدا می‌کند.', 1),
('savushun', 'سووشون', 'سیمین دانشور', 'انتشارات خوارزمی', 1, 320000, 0, 312, 1401, '978-964-00-0002-8', 8, '2026-05-02', 2, 0, 1, 'سووشون نخستین رمان فارسی نوشته‌شده به قلم یک زن است؛ روایتی از شیراز در سال‌های اشغال ایران و زندگی زری، زنی که در میانه سنت و مدرنیته ایستاده است.', 1),
('kelidar-1', 'کلیدر (جلد اول)', 'محمود دولت‌آبادی', 'نشر چشمه', 1, 480000, 15, 640, 1401, '978-964-00-0003-5', 6, '2026-10-01', 5, 2, 2, 'جلد اول از رمان ده‌جلدی کلیدر، حماسه‌ای از زندگی ایل و روستا در خراسان. دولت‌آبادی در این اثر زبان و زندگی مردم کویر را به تصویر می‌کشد.', 1),
('cheraghha', 'چراغ‌ها را من خاموش می‌کنم', 'زویا پیرزاد', 'نشر مرکز', 1, 265000, 0, 268, 1402, '978-964-00-0004-2', 11, '2026-07-19', 6, 1, 3, 'روایت زندگی روزمره یک زن خانه‌دار در آبادان دهه چهل؛ داستانی آرام و دقیق از خواستن، رضایت و رهایی.', 1),
('modir-modrese', 'مدیر مدرسه', 'جلال آل‌احمد', 'انتشارات فردوس', 1, 165000, 0, 190, 1400, '978-964-00-0005-9', 0, '2025-11-11', 12, 3, 4, 'مدیر مدرسه با زبانی طنزآمیز و نقدی اجتماعی، روزگار یک معلم و مدیر مدرسه در نظام آموزشی دهه سی را روایت می‌کند.', 1),
('melat-eshgh', 'ملت عشق', 'الیف شافاک', 'نشر ققنوس', 1, 395000, 20, 512, 1402, '978-964-00-0006-6', 9, '2026-08-08', 4, 5, 0, 'دو روایت موازی از شمس و مولانا و زندگی زنی امروزی؛ داستانی درباره عشق، تحول و پذیرش.', 1),
('ensan-mana', 'انسان در جست‌وجوی معنا', 'ویکتور فرانکل', 'انتشارات درسا', 2, 215000, 10, 232, 1401, '978-964-00-0007-3', 14, '2026-04-21', 7, 3, 1, 'فرانکل، روان‌پزشک اتریشی، بر پایه تجربه خود در اردوگاه‌های نازی، معنادرمانی را معرفی می‌کند: توان انسان برای یافتن معنا حتی در سخت‌ترین شرایط.', 1),
('ghodrat-aknun', 'قدرت اکنون', 'اکهارت تله', 'انتشارات کیمیا', 2, 248000, 0, 288, 1400, '978-964-00-0008-0', 7, '2026-02-12', 11, 1, 2, 'کتابی درباره حضور در لحظه و رهایی از ذهن پرگویی که گذشته و آینده را جای حال می‌نشاند.', 1),
('vaghti-nietzsche', 'وقتی نیچه گریست', 'اروین یالوم', 'نشر کارنامه', 2, 375000, 12, 420, 1401, '978-964-00-0009-7', 5, '2026-06-30', 8, 4, 3, 'روایتی تخیلی از گفت‌وگوی درمانی میان یوزف برویر و فریدریش نیچه؛ اثری درباره فقدان، پذیرش و شفافیت احساسات.', 1),
('shahnameh', 'شاهنامه (دوره کامل)', 'فردوسی', 'نشر هرمس', 8, 690000, 25, 1080, 1402, '978-964-00-0010-3', 4, '2026-09-02', 1, 2, 0, 'حماسه ملی ایران با تصحیح معتبر و کاغذ تحریر؛ روایت پهلوانان، پادشاهان و اسطوره‌های ایرانی از آغاز تا پایان.', 1),
('masnavi', 'مثنوی معنوی', 'مولانا', 'نشر امیرکبیر', 8, 540000, 0, 880, 1401, '978-964-00-0011-0', 3, '2026-03-08', 9, 5, 1, 'مثنوی معنوی، اثر سترگ مولانا جلال‌الدین بلخی، مجموعه‌ای از حکایت‌ها و اندیشه‌های عرفانی که قرن‌ها خوانده و شرح شده است.', 1),
('golestan', 'گلستان سعدی', 'سعدی', 'انتشارات خوارزمی', 8, 195000, 15, 240, 1400, '978-964-00-0012-7', 18, '2026-01-25', 13, 3, 2, 'گلستان، مجموعه حکایت‌ها و پندهای سعدی شیرازی، با نثری آهنگین و تصویری که هنوز تازه است.', 1),
('divan-hafez', 'دیوان حافظ', 'حافظ', 'نشر ققنوس', 8, 385000, 0, 512, 1401, '978-964-00-0013-4', 10, '2026-07-01', 10, 1, 3, 'دیوان حافظ با غزل‌های جاودانه‌ای درباره عشق، رندی و امید؛ همراه با شرح واژه‌ها برای خوانندگان امروز.', 1),
('tarikh-bastan', 'تاریخ ایران باستان', 'حسن پیرنیا', 'نشر اساطیر', 4, 620000, 18, 720, 1400, '978-964-00-0014-1', 5, '2026-08-22', 14, 2, 4, 'پژوهشی کلاسیک درباره تاریخ ایران پیش از اسلام؛ از ماد و هخامنشی تا اشکانی و ساسانی.', 1),
('tarikh-tamadon-1', 'تاریخ تمدن (جلد اول)', 'ویل دورانت', 'علمی و فرهنگی', 4, 780000, 0, 920, 1402, '978-964-00-0015-8', 2, '2026-06-11', 15, 4, 0, 'جلد نخست از مجموعه تاریخ تمدن، درباره مشرق‌زمین و شکل‌گیری نخستین تمدن‌های انسانی.', 1),
('tarikhche-zaman', 'تاریخچه زمان', 'استیون هاوکینگ', 'نشر نو', 3, 310000, 0, 256, 1401, '978-964-00-0016-5', 13, '2026-05-27', 16, 3, 1, 'از انفجار بزرگ تا سیاه‌چاله‌ها؛ هاوکینگ کیهان را برای خواننده غیرمتخصص روایت می‌کند.', 1),
('jahan-pust-gerdu', 'جهان در پوست گردو', 'استیون هاوکینگ', 'نشر نو', 3, 285000, 10, 224, 1400, '978-964-00-0017-2', 9, '2026-04-05', 17, 5, 2, 'هاوکینگ در این کتاب از نظریه‌های نوین فیزیک، ابرتقارن و سفر در زمان می‌گوید.', 1),
('riazi-zendegi', 'ریاضیات برای زندگی', 'کیت ییتس', 'نشر مازیار', 3, 230000, 0, 208, 1401, '978-964-00-0018-9', 16, '2026-02-19', 18, 0, 3, 'کاربردهای روزمره ریاضی از تصمیم‌گیری تا مدیریت پول، با زبانی ساده و مثال‌های واقعی.', 1),
('falsafe-daghighe', 'فلسفه در چند دقیقه', 'مارکوس ویکس', 'نشر شهرتاش', 6, 245000, 12, 260, 1402, '978-964-00-0019-6', 8, '2026-09-27', 19, 1, 4, 'مروری سریع و روشن بر مهم‌ترین اندیشه‌های فلسفی، از پیش‌سقراطی‌ها تا فلسفه معاصر.', 1),
('chonin-goft-zarathustra', 'چنین گفت زرتشت', 'فریدریش نیچه', 'نشر آگه', 6, 355000, 0, 384, 1401, '978-964-00-0020-2', 6, '2026-03-30', 20, 4, 0, 'کتابی شاعرانه و پرچالش درباره ابرانسان، اراده معطوف به قدرت و بازارزیابی همه ارزش‌ها.', 1),
('jomhur', 'جمهور', 'افلاطون', 'انتشارات خوارزمی', 6, 290000, 0, 460, 1400, '978-964-00-0021-9', 4, '2025-12-09', 21, 2, 1, 'گفت‌وگویی بنیادین درباره عدالت، شهر آرمانی و تربیت؛ یکی از اثرگذارترین متن‌های فلسفه سیاسی.', 1),
('afsanehaye-kehan', 'افسانه‌های کهن ایرانی', 'گردآوری: مهدی رجایی', 'نشر افق', 5, 178000, 15, 160, 1402, '978-964-00-0022-6', 20, '2026-10-12', 22, 0, 2, 'مجموعه‌ای از افسانه‌های ایرانی برای کودکان؛ با روایتی ساده و تصویرگری گرم.', 1),
('ghesehaye-khub', 'قصه‌های خوب برای بچه‌های خوب', 'مهدی آذریزدی', 'نشر امیرکبیر', 5, 210000, 0, 196, 1401, '978-964-00-0023-3', 15, '2026-07-08', 23, 3, 3, 'بازنویسی داستان‌های کلاسیک فارسی برای کودکان؛ کتابی که نسل‌ها با آن بزرگ شده‌اند.', 1),
('matilda', 'ماتیلدا', 'رولد دال', 'نشر افق', 5, 165000, 20, 232, 1400, '978-964-00-0024-0', 12, '2026-01-14', 24, 5, 4, 'داستان دختری باهوش و کتاب‌خوان که با معلمی مهربان و مدیری سخت‌گیر روبه‌رو می‌شود؛ پر از طنز و خیال.', 1),
('adat-atomi', 'عادت‌های اتمی', 'جیمز کلیر', 'نسل نواندیش', 7, 320000, 18, 320, 1402, '978-964-00-0025-7', 10, '2026-09-19', 25, 1, 0, 'روشی عملی برای ساختن عادت‌های کوچک و پایدار؛ با تمرکز بر تغییر سیستم به‌جای تغییر هدف.', 1),
('ghodrat-adat', 'قدرت عادت', 'چارلز دوهیگ', 'نسل نواندیش', 7, 298000, 0, 344, 1401, '978-964-00-0026-4', 7, '2026-05-16', 26, 2, 1, 'دوهیگ نشان می‌دهد عادت‌ها چگونه شکل می‌گیرند و چطور می‌توان چرخه آن‌ها را برای تغییر رفتار بازنویسی کرد.', 1),
('haft-adat', 'هفت عادت مردمان مؤثر', 'استیون کاوی', 'نسل نواندیش', 7, 340000, 10, 400, 1400, '978-964-00-0027-1', 6, '2026-08-30', 27, 4, 2, 'چارچوبی کلاسیک برای رشد فردی و حرفه‌ای؛ از ابتکار عمل تا هم‌آفرینی و بازآفرینی.', 1);
